import {randomUUID as id}from'node:crypto';
import {readFile,readdir}from'node:fs/promises';
import {isolatedBooking,bookingMigration,read,write}from'../../tests/support/h2-booking-isolated.ts';
import {H4011ModificationAdapter}from'../../src/infrastructure/postgres/h4-modification-adapter.ts';
import {H4009ConfirmationAdapter}from'../../src/infrastructure/postgres/h4-confirmation-adapter.ts';
import {H3013OwnEconomicsAdapter}from'../../src/infrastructure/postgres/h3-own-economics-adapter.ts';
export {read,write};
export const now=()=>new Date().toISOString();
export async function database(){const h=await isolatedBooking('h6003auditor',61600);for(const file of(await readdir('supabase/migrations')).filter(x=>x.endsWith('.sql')&&x>bookingMigration).sort())await h.migration.unsafe(await readFile('supabase/migrations/'+file,'utf8'));return {...h,modifications:new H4011ModificationAdapter(h.runtime,h.f1,h.f2),confirmations:new H4009ConfirmationAdapter(h.runtime,h.f1,h.f2),ownEconomics:new H3013OwnEconomicsAdapter(h.runtime,h.f1,h.f2)};}
export async function fixture(h:any,{names=4,bCount=2}={}){
 const opp=h.input();await h.adapter.apply(await h.auth(),write,opp);
 const evidence=async(claim:string,coverage:string,target:string,contextKind='other',time=now())=>{const q=h.req('evidence',{claim,coverage,certainty:'reviewed',source_kind:'manual'},target,contextKind);await h.evidence.apply(await h.auth(),write,{...q,occurredAt:time,coverage});return q.targetId;};
 const proof=(claim:string,target=opp.targetId,time=now())=>evidence(claim,target,target,'other',time);
 const unit=await h.cat('unit',{name:'SYNTHETIC own auditor group',definition:'fixed group'}),form=await h.cat('pricing_form',{name:'SYNTHETIC own fixed',definition:'fixed'}),sources=[];
 for(const name of['Rafting','Dinner','Whole house']){const service=await h.cat('service',{name:'SYNTHETIC auditor '+name,nature:'external'}),tariff=await h.com('tariff',{label:'SYNTHETIC audit',price_state:'confirmed',amount:'900.00',cost_state:'confirmed',cost_amount:'700.00',vat_treatment:'included',unit_revision_id:unit.revision,pricing_form_revision_id:form.revision},service);sources.push({service,tariff});}
 const modalities=[10,bCount].map((participants,i)=>({id:id(),name:'SYNTHETIC modality '+i,participants,independent:true,selectable:true,conditions:'SYNTHETIC auditor exact',finalPersonPrice:i?'120.00':'150.00',manualReason:'SYNTHETIC human exact',definitive:true,lines:[...(i?[]:[{kind:0,date:'2026-11-20'}]),{kind:1,date:'2026-11-20'},{kind:2,date:'2026-11-20'},...(i?[]:[{kind:2,date:'2026-11-21'}])].map(x=>({id:id(),serviceRevisionId:sources[x.kind].service.revision,unitRevisionId:unit.revision,tariffRevisionId:sources[x.kind].tariff.revision,quantity:'1',included:true,independent:false,selectable:false,date:x.date,datePending:false,priceBasis:'fixed',costMaterial:true,sourceRef:'SYNTHETIC audit exact source'}))}));
 const scope='SYNTHETIC audit E2E03 scope',terms={version:'AUD003-TERMS1',text:'SYNTHETIC exact terms; no mandate',sourceRef:'SYNTHETIC audit retained'},content={scope,terms,pending:[],modalities},proposalId=id(),versionId=id(),acceptanceId=id(),accepterId=id(),designationId=id();
 await h.identities.apply(await h.auth(),write,{action:'create_entity',operationId:id(),targetId:accepterId,kind:'contact',expectedVersion:0,sourceRef:'SYNTHETIC audit',evidenceRef:'SYNTHETIC audit identity',reason:'SYNTHETIC audit',verified:true,displayName:'SYNTHETIC AUD003 CLIENT'});
 await h.identities.apply(await h.auth(),write,{action:'designate',operationId:id(),targetId:designationId,relatedId:accepterId,contextId:opp.targetId,kind:'primary_contact',expectedVersion:0,sourceRef:'SYNTHETIC audit',evidenceRef:'SYNTHETIC faculty',reason:'SYNTHETIC',verified:true,happenedAt:new Date(Date.now()-1000).toISOString()});
 const time=now(),commercialProof=(claim:string,t=time)=>evidence(claim,scope,opp.targetId,'opportunity',t),base={opportunityId:opp.targetId,proposalId,sourceRef:'SYNTHETIC audit real fictitious call',reason:'SYNTHETIC audit',expectedOpportunityRevision:2},prepare={...base,action:'prepare',operationId:id(),expectedOpportunityRevision:1,expectedRevision:0,content},fix={...base,action:'fix',operationId:id(),expectedRevision:1,versionId},issue={...base,action:'issue',operationId:id(),expectedRevision:2,versionId,coverage:scope,at:time,issuance:{issuedAt:time,limits:[]},evidenceId:await commercialProof(`offer:issue:${versionId}:${time}:7`)},register={...base,action:'register',operationId:id(),expectedRevision:3,versionId,acceptanceId,coverage:scope,at:time,accepterId,designationId,channel:'phone',terms,authorityEvidenceId:await commercialProof(`acceptance:authority:${versionId}:${accepterId}:${designationId}`),evidenceId:await commercialProof(`acceptance:agree:${versionId}:${acceptanceId}:${accepterId}:phone`)};
 const reviewEvidence:any={};for(const aspect of['prices','availability','conditions','capacity'])reviewEvidence[aspect]=await commercialProof(`offer:review:${versionId}:${acceptanceId}:accept:${aspect}`);
 const verify={...base,action:'verify',operationId:id(),expectedRevision:4,versionId,acceptanceId,coverage:scope,at:time,reviewEvidence,won:true};
 const services=sources.map(({service},kind)=>{const contributions=modalities.flatMap(m=>m.lines.filter(l=>l.serviceRevisionId===service.revision).map(l=>({id:id(),lineId:l.id,modalityId:m.id,quantity:l.quantity,attendees:m.participants,certainty:'estimated'})));return{id:id(),serviceRevisionId:service.revision,nature:'external',variant:null,provider:null,place:null,schedule:null,contributions,nights:kind===2?['2026-11-20','2026-11-21'].map(date=>({id:id(),date,contributionIds:contributions.filter(c=>modalities.flatMap(m=>m.lines).find(l=>l.id===c.lineId)!.date===date).map(c=>c.id)})):[]};});
 const detail:any={services,participants:[],assignments:[]},hash=async(value:any)=>(await h.observer`select encode(crm_crypto.digest(convert_to(${JSON.stringify(value)}::text::jsonb::text,'UTF8'),'sha256'),'hex') h`)[0].h;
 for(let i=0;i<names;i++){const who=id(),house=services[2],night=house.nights[0];detail.participants.push({id:who,name:'SYNTHETIC AUD003 Participant '+i,contactId:null,evidenceId:await commercialProof(`booking:participant:${acceptanceId}:${who}`,now()),sourceRef:'SYNTHETIC AUD003 verified necessity'});detail.assignments.push({participantId:who,serviceId:house.id,nightId:night.id,necessity:'SYNTHETIC necessary house guest registration subset',evidenceId:await commercialProof(`booking:nominal:${acceptanceId}:${house.id}:${night.id}`,now())});}
 const bookingId=id(),q:any={operationId:id(),bookingId,opportunityId:opp.targetId,acceptanceId,proposalId,versionId,coverage:scope,terms,expectedRevision:5,expectedOpportunityRevision:3,sourceRef:'SYNTHETIC audit E2E03',reason:'SYNTHETIC audit conversion',evidenceId:await commercialProof(`booking:detail:${acceptanceId}:${await hash(detail)}`,now()),detail,route:'direct'},stages:any=[{kind:'proposal',command:prepare},{kind:'proposal',command:fix},{kind:'offer',command:issue},{kind:'acceptance',command:register},{kind:'acceptance',command:verify}];
 const record=async()=>{const q=h.req('document',{relation:'original',content_ref:'SYNTHETIC manual request',content_kind:'manual_record',storage_state:'reference_only'},bookingId,'booking');await h.evidence.apply(await h.auth(),write,{...q,occurredAt:now()});return q.targetId;};
 const view=()=>h.auth().then((a:any)=>h.booking.read(a,read,bookingId));
 return {opp,content,terms,modalities,services,q,stages,bookingId,proposalId,versionId,acceptanceId,accepterId,designationId,proof,commercialProof,evidence,hash,record,view,run:()=>h.auth().then((a:any)=>h.booking.direct(a,write,stages,q))};
}
export async function modification(h:any,f:any,scope:any,desired:any,aspects=Object.keys(desired),revision=1){
 const modificationId=id(),partId=id(),see=()=>h.auth().then((a:any)=>h.modifications.read(a,read,modificationId,f.bookingId)),proof=(claim:string,target:string,time=now())=>f.proof(claim,target,time);
 const attest=async(q:any)=>({...q,evidenceId:await proof(`modification:${q.action}:${await f.hash(Object.fromEntries(Object.entries(q).filter(([k,v])=>!['operationId','evidenceId'].includes(k)&&v!==undefined)))}`,modificationId,q.at)});
 const command=async(action:string,data:any,change:any={})=>attest({action,operationId:id(),modificationId,bookingId:f.bookingId,expectedRevision:(await see())?.revision??0,sourceRef:'SYNTHETIC independent audit exact source',reason:'SYNTHETIC independent audit authorized change',at:now(),evidenceId:id(),data,...change});
 const request=async()=>command('request',{requester:{kind:'internal',id:h.actorId},cause:'SYNTHETIC real fictitious scoped need',type:'change',recordId:await f.record(),parts:[{id:partId,scope,expectedScopeRevision:revision,desired,aspects,dependencies:[]}]});
 const evaluate=(extra:any={})=>command('evaluate',{policy:{id:'SYNTHETIC approved test policy',version:'1',terms:f.terms},impacts:{commercial:'SYNTHETIC verified client agreement',operational:'SYNTHETIC precisely scoped',economic:'pending'},...extra});
 const approve=async()=>{const v=await see(),part=v.parts.find((p:any)=>p.id===partId),digest=await f.hash(Object.fromEntries(Object.entries(part).filter(([k])=>!['review','applied'].includes(k))));return command('approve',{partIds:[partId],proofs:{[partId]:{client:await proof('modification:client:'+digest,f.bookingId),provider:await proof('modification:provider:'+digest,f.bookingId),constraints:await proof('modification:constraints:'+digest,f.bookingId)}}});};
 const apply=async()=>command('apply',{partIds:[partId],approvalRevision:(await see()).approval.revision}),run=(q:any)=>h.auth().then((a:any)=>h.modifications.apply(a,write,q)),prepare=async()=>{await run(await request());await run(await evaluate());await run(await approve());return apply();};
 const ratify=async(what:string[])=>{const p=(await see()).parts.find((p:any)=>p.id===partId),validUntil='2030-01-01T00:00:00Z',digest=await f.hash({part:Object.fromEntries(Object.entries(p).filter(([k])=>k!=='review')),aspects:what,validUntil});return command('ratify',{partIds:[partId],aspects:what,validUntil,proofId:await proof('modification:ratify:'+digest,f.bookingId),result:'SYNTHETIC independent precise ratification'});};
 return {modificationId,partId,scope,see,attest,command,request,evaluate,approve,apply,run,prepare,ratify};
}
